from pathlib import Path
import re
b=Path('edit.Paper/output');s=(b/'20261025_08_article_revised.md').read_text()
def para(prefix,new):
 global s
 p=[p for p in s.split('\n\n') if p.startswith(prefix)]
 assert len(p)==1,(prefix,len(p));s=s.replace(p[0],new,1)
para('This computational study was conducted', 'This study was conducted at Shanghai University of Medicine & Health Sciences, Shanghai, China. The analysis combined herb–compound and compound–gene data, functional enrichment, paired tumour-expression profiles, and exploratory molecular docking.')
para('Herb–ingredient records from TCMSP', '''Herb–ingredient records were obtained from TCMSP and linked to PubChem compound identifiers (CIDs) by matching lower-case compound names to a synonym table.^4,5^ Compound-associated genes were assembled from BindingDB, BATMAN-TCM known and predicted interactions, and the IUPHAR/BPS Guide to PHARMACOLOGY.^6,7,8^ The BindingDB source was the September 2024 dataset, with UniProt identifiers mapped using the file dated 5 September 2024. Recorded associations from these sources were retained, and BATMAN-TCM predictions were included when the prediction score exceeded 0.80. The resulting CID–gene records were combined and gene symbols deduplicated within each CID. TCMSP supplied the herb–ingredient inventory; the retained gene associations came from the three target resources listed above.''')
para('The XYT input contained', '''The selected XYT set comprised E Zhu, Bai Shao, Dang Gui, Chai Hu, Qing Pi, Huang Yao Zi, Xia Ku Cao, Zao Jiao Ci, Mu Dan Pi, Bai Zhu, Fu Ling, Bai Mao Xia Ku Cao, Xuan Shen, and Zhe Bei Mu. ZBM and XKC records were extracted by their Chinese herb names and processed using the same workflow. Duplicate herb–compound records were collapsed within each set. Distinct CIDs were counted at three stages: all mapped ingredients, ingredients linked to retained genes, and ingredients linked to disease-overlapping genes.''')
para('The GeneCards export contained', '''Thyroid-tumour-associated genes were obtained from a GeneCards export containing 12,987 unique gene symbols.^9^ The complete exported gene list was used for all three comparisons. Ingredient-associated gene symbols were split on semicolons, deduplicated, and intersected with the disease list to define the ZBM, XKC, and XYT candidate sets.''')
s=s.replace("We used the submitter's fRMA-normalised log2 expression matrix without further transformation or normalisation.","The submitter's fRMA-normalised log2 expression matrix was used for analysis.")
s=s.replace('the archived disease list','the disease list')
para('For the original functional analysis', '''Unique gene symbols were mapped to Entrez identifiers with `bitr` and org.Hs.eg.db, and all returned identifiers were used for enrichment analysis in clusterProfiler.^12^ GO analysis covered biological process (BP), molecular function (MF), and cellular component (CC); KEGG analysis used human annotations. Enrichment was assessed by upper-tail hypergeometric tests with Benjamini–Hochberg correction, `pvalueCutoff = 0.05`, and `qvalueCutoff = 0.2`. The default annotation backgrounds comprised 18,888 genes for BP, 18,522 for MF, 19,894 for CC, and 8,859 for KEGG. Terms with adjusted P <0.05 were reported.''')
s=s.replace('Missing bars indicate that a term was absent from an exported significant-result table. The figures describe annotation profiles; no formal between-herb comparison of enrichment or efficacy was performed.', 'Missing bars indicate terms absent from the significant-result tables. These figures provide a descriptive comparison of annotation profiles.')
para('Ligands were prepared with Open Babel', '''Ligands were prepared with Open Babel, and receptor structures were obtained from RCSB PDB.^13,14^ Initial screening used AutoDock Vina, and supplementary β-sitosterol docking used smina.^15,16^ Structural assessment focused on human CYP3A4 (6UNI) and apo CaV3.2/CACNA1H (9AYG).^14,17^ The bacterial 4P5A structure was excluded from the human-target analysis. The initial Vina protocol specified a 20 × 20 × 20 Å search box centred on the mean receptor ATOM coordinates rounded to whole angstroms, exhaustiveness 32, and five CPU threads. Supplementary smina docking used exhaustiveness 8, nine output modes, and one CPU thread. The search box was defined from the extracted reference structure with `--autobox_add 4`. The minimum-score poses were examined alongside receptor identity, cofactor retention, and the residues used to define the search region.''')
s=s.replace('Archived docking results for β-sitosterol were also reviewed as exploratory structural observations.', 'Exploratory docking of β-sitosterol was included to examine candidate compound–protein interactions.')
s=s.replace('The saved GO result tables contained','GO analysis identified').replace('The saved KEGG tables contained','KEGG analysis identified')
s=s.replace('but was absent from the exported significant ZBM table','but was absent from the significant ZBM results')
s=s.replace(' Pathway labels describe shared annotations and do not imply treatment of the named diseases.','')
s=s.replace('This descriptive display does not test differences between groups. Full enrichment results and figure source rows accompany the manuscript.','Full enrichment results and figure source data accompany the manuscript.')
para('β-Sitosterol (CID 222284) was represented', '''β-Sitosterol (CID 222284) was common to all three ingredient sets and was selected for structural exploration. Repeated CID–receptor combinations under different herb labels represented the same compound–protein pair.''')
para('Supplementary smina outputs gave', '''The minimum smina scores were −9.12 kcal/mol for CYP3A4 (6UNI) and −9.68 kcal/mol for CaV3.2 (9AYG) (Figure 5). The CYP3A4 receptor was prepared without its haem cofactor, while the automatic box reference included both haem and the crystallographic inhibitor. For 9AYG, the box reference contained several non-protein residue types. The displayed poses are therefore treated as exploratory structural outputs.''')
s=s.replace(' The bacterial 4P5A entry was excluded from human-target interpretation (see Methodology). These poses are exploratory structural outputs and are not validated binding evidence.', ' The poses should be interpreted in light of the receptor-preparation and search-region limitations described in the text.')
para('The expression results did not provide', '''The gene-level expression findings warrant a more cautious interpretation than the gene-set results. POLB showed a statistically significant change of less than 0.1 log2 units, whereas CACNA1H and CYP3A4 showed no significant expression difference. Transcript abundance and protein activity are distinct measures, so the next step is functional testing of the proposed interactions. CYP3A4 is involved in vandetanib metabolism,^20^ making drug metabolism another plausible context for its association with herbal compounds. The docking poses offer limited support because CYP3A4 lacked its haem cofactor and the automatic search regions were not validated binding sites.''')
para('Several methodological limitations affect', '''The findings are subject to several limitations. Target assignments combine recorded and predicted associations with different evidence strengths. BindingDB records were integrated without an organism- or affinity-based restriction, which limits interpretation as human therapeutic targets. The broad disease list and annotation-wide GO/KEGG backgrounds may favour well-annotated genes and shared pathways. The disease-restricted transcriptome analysis addressed background choice for expression overlap, while gene correlation and database coverage remain relevant to the functional results. The expression cohort represents PTC, and differences in tissue composition may contribute to the observed changes. The study therefore supports disease associations that require testing in treatment-exposed models with chemically characterised preparations.''')
para('The next experimental step is', '''Further work should combine concentration–response experiments, non-malignant controls, and target perturbation with binding or functional assays. Structural follow-up should retain essential cofactors, define the binding site explicitly, and evaluate the docking protocol using a reference ligand.''')
s=s.replace('**Conclusion:** Genes associated with XYT and XKC were over-represented among genes altered in PTC tissue. This supports their relevance for further biological investigation, but does not establish a treatment effect or validate the proposed compound–protein interactions.', '**Conclusion:** XYT- and XKC-associated genes were over-represented among genes altered in PTC tissue. These associations identify candidates for functional investigation of the selected herbs.')
s=s.replace('The findings narrow the hypotheses for further testing; they do not establish herb efficacy, synergy, or the proposed compound–protein interactions.', 'These findings prioritise disease-associated genes for functional studies of the selected herbs.')
# Patient-consent facts stated once, without an audit-style account of actions not taken.
para('No new consent was obtained', 'The study used publicly available, de-identified GEO data for secondary analysis.')
s=re.sub(r' +\n','\n',s)
p=b/'20261025_12_article_polished.md';assert not p.exists();p.write_text(s)
print(p)
